export function getFallbackPlayersForTeam(team: string): Player[] {
  const norm = (team || "").toLowerCase().trim();
  const canonical = TEAM_ALIASES[norm] || team;

  if (SAMPLE_BUNDESLIGA_PLAYERS[canonical]) {
    return SAMPLE_BUNDESLIGA_PLAYERS[canonical];
  }

  // Check partial key match
  for (const [key, players] of Object.entries(SAMPLE_BUNDESLIGA_PLAYERS)) {
    if (key.toLowerCase().includes(norm) || norm.includes(key.toLowerCase())) {
      return players;
    }
  }

  // Return Bayern as ultimate safe baseline
  return SAMPLE_BUNDESLIGA_PLAYERS["Bayern Munich"];
}
